// Generated by `just generate` from `src/plugins/claudetto/slices/setup/domain/tiers.ts`. Edit the source and run `just generate`.
// The account tiers of setup, as pure functions: which account a status names, and the picks of each account.
// Pro is the baseline. Max 5x and Max 20x get more parallel subagents and a higher effort.
// An account with no login gets no picks, because setup knows nothing about its budget.
// Claude Code already scales the plan mode agents and the usage warnings by tier, so setup does not set them.
// The CLI reads `claude auth status --json`, and the adapter gives the parsed value here.

import {
  SUBAGENTS_MAX_5X,
  SUBAGENTS_MAX_20X,
  SUBAGENTS_PRO,
} from "../limits.ts";
import { isObject } from "./merge.ts";
import type { Json } from "./types.ts";

/** The accounts that setup tells apart. `pro` is the baseline, and also the fallback for each account with no own row. */
export type Account = "pro" | "max5x" | "max20x" | "api" | "none";

/** The rate limit tier that Claude Code gives a Max 5x account. */
export const RATE_TIER_MAX_5X = "default_claude_max_5x";
/** The rate limit tier that Claude Code gives a Max 20x account. */
export const RATE_TIER_MAX_20X = "default_claude_max_20x";

/** The picks of one account: the stored effort, and the subagent cap in `env`. */
const picks = (effort: string, subagents: number): Json => ({
  effortLevel: effort,
  env: { CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS: String(subagents) },
});

/** The picks of each account that has a login. The `none` account has no entry. */
export const PICKS: Record<Exclude<Account, "none">, Json> = {
  pro: picks("high", SUBAGENTS_PRO),
  max5x: picks("xhigh", SUBAGENTS_MAX_5X),
  max20x: picks("xhigh", SUBAGENTS_MAX_20X),
  api: picks("high", SUBAGENTS_PRO),
};

/**
 * The account of `status`, the parsed output of `claude auth status --json`, and of `rateLimitTier`.
 * A status that is not an object, or that says `loggedIn: false`, gives `none`.
 * A `subscriptionType` of `max` needs `rateLimitTier` to tell 5x from 20x, and gives `pro` without it.
 * Another subscription type (`pro`, `team`, `enterprise`) gives `pro`.
 * No subscription type with a login gives `api`, because that account pays for each use.
 */
export const accountOf = (status: unknown, rateLimitTier?: string): Account => {
  if (!isObject(status) || status["loggedIn"] === false) return "none";
  const subscription = status["subscriptionType"];
  if (subscription === "max") {
    if (rateLimitTier === RATE_TIER_MAX_20X) return "max20x";
    if (rateLimitTier === RATE_TIER_MAX_5X) return "max5x";
    return "pro";
  }
  if (typeof subscription === "string") return "pro";
  const loggedIn = status["loggedIn"];
  const hasLogin =
    loggedIn === true ||
    (loggedIn === undefined && typeof status["authMethod"] === "string");
  return hasLogin ? "api" : "none";
};

/** The picks of `account`, or `undefined` when setup writes none. */
export const picksOf = (account: Account): Json | undefined =>
  account === "none" ? undefined : PICKS[account];
